import xml.etree.ElementTree as ET
import tempfile, os

tmpdir = tempfile.gettempdir\(\)
doc_path = os.path.join\(tmpdir, 'docx-check', 'unpacked', 'word', 'document.xml'\)

tree = ET.parse\(doc_path\)
root = tree.getroot\(\)

W = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'

def wtag\(name\):
    return f'{{{W}}}{name}'

def get_para_style\(para\):
    pPr = para.find\(wtag\('pPr'\)\)
    if pPr is not None:
        pStyle = pPr.find\(wtag\('pStyle'\)\)
        if pStyle is not None:
            return pStyle.get\(wtag\('val'\)\)
    return 'Normal'

def get_para_text\(para\):
    texts = []
    for elem in para.iter\(\):
        if elem.tag == wtag\('t'\):
            texts.append\(elem.text or ''\)
        elif elem.tag == wtag\('br'\) or elem.tag == wtag\('cr'\):
            texts.append\('\\n'\)
    return ''.join\(texts\)

def get_cell_text\(cell\):
    paras = []
    for para in cell.findall\(f'.//{wtag\("p"\)}'\):
        t = get_para_text\(para\)
        paras.append\(t\)
    return ' '.join\(t for t in paras if t\)

body = root.find\(f'.//{wtag\("body"\)}'\)

for child in body:
    tag = child.tag.split\('}'\)[-1] if '}' in child.tag else child.tag

    if tag == 'p':
        style = get_para_style\(child\)
        text = get_para_text\(child\)
        print\(f'[STYLE: {style}] {text}'\)

    elif tag == 'tbl':
        print\('[TABLE]'\)
        row_num = 0
        for tr in child.findall\(wtag\('tr'\)\):
            row_num += 1
            cells = []
            for tc in tr.findall\(wtag\('tc'\)\):
                cells.append\(get_cell_text\(tc\)\)
            print\(f'  Row {row_num}: ' + ' | '.join\(cells\)\)
        print\('[/TABLE]'\)

PYEOF)

